function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 50) return 'grid needs 2 to 50 rows.';
  const cols = grid[0].length;
  if (cols < 2 || cols > 50) return 'Each row needs 2 to 50 values.';
  if (grid.some(line => line.length !== cols)) return 'All rows must have the same length.';
  if (grid.some(line => line.some(v => v < 1 || v > 2500))) return 'Each value is between 1 and 2500.';
  return null;
}

