function zigzagTraversal(grid) {
  const result = [];
  let take = true;
  for (let row = 0; row < grid.length; row++) {
    const cols = grid[row].length;
    for (let step = 0; step < cols; step++) {
      const col = row % 2 === 0 ? step : cols - 1 - step;
      if (take) {
        result.push(grid[row][col]);
      }
      take = !take;
    }
  }
  return result;
}

