function zigzagTraversal(grid) {
  // Write out the whole snake walk first, then keep the cells at even positions of it.
  const walk = [];
  grid.forEach((line, r) => walk.push(...(r % 2 === 1 ? [...line].reverse() : line)));
  return walk.filter((_, i) => i % 2 === 0);
}

