function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // Large grids are close to 50 by 50; small ones mix odd and even widths, with few or many distinct values.
  const rows = size === 'large' ? 40 + pick(11) : 2 + pick(4);
  const cols = size === 'large' ? 40 + pick(11) : 2 + pick(4);
  const top = size === 'large' ? 2500 : [2, 9, 2500][pick(3)];
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => 1 + pick(top)))];
}
